export default function ModulePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const slug = params.slug as string;

  const [repo, setRepo] = useState<Repository | null>(null);
  const [module_, setModule] = useState<Module | null>(null);
  const [loading, setLoading] = useState(true);
  const [allModules, setAllModules] = useState<Module[]>([]);

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }
        setRepo(found);

        const [mod, mods] = await Promise.all([
          api.wikis.getModule(found.id, slug).catch(() => null),
          api.wikis.listModules(found.id).catch(() => []),
        ]);
        setModule(mod);
        setAllModules(mods);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name, slug]);

  const displayModule = module_ ?? {
    name: slug.charAt(0).toUpperCase() + slug.slice(1).replace(/-/g, ' '),
    description: 'Authentication module handles all aspects of user identity and access. It provides JWT-based session management, password hashing, token lifecycle, and HTTP middleware for protecting routes.',
    file_paths: ['src/auth/'],
    file_count: 18,
  };

  // Build sidebar items, marking current module as active
  const sidebarSections = allModules.length > 0
    ? [{
        label: 'Modules',
        items: allModules.map((m) => ({
          label: m.name,
          href: `modules/${m.slug}`,
          active: m.slug === slug,
        })),
      }, ...SIDEBAR_SECTIONS]
    : SIDEBAR_SECTIONS.map((s) => ({
        ...s,
