            />
            <span>Last synced:</span>
            <span style={{ fontFamily: "'Fira Code', monospace", color: 'var(--primary-light)' }}>
              f6c11de
            </span>
            <span>· 2 hours ago</span>
            <span>· Auto-generated from source</span>
          </div>

          <div className="content-body">
            <p style={{ color: 'var(--text-secondary)', lineHeight: 1.8, marginBottom: 24 }}>
              {displayModule.description}
            </p>
          </div>

          <InfoBox variant="info">
            <strong>Auto-generated:</strong> This page is generated directly from source code in{' '}
            <code>{displayModule.file_paths?.[0] ?? 'src/'}</code>. All function signatures, file sizes, and dependency
            data are extracted at analysis time and stay in sync with every commit.
          </InfoBox>

          {/* File Location */}
          <h2 id="file-location" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            File Location
          </h2>
          <CodeBlock language="text">
            {`${displayModule.file_paths?.[0] ?? 'src/auth/'}
  ├── login.py         (245 lines)
  ├── session.py       (189 lines)
  ├── tokens.py        (312 lines)
  └── middleware.py    (201 lines)`}
          </CodeBlock>

          {/* Key Components */}
          <h2 id="key-components" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Key Components
          </h2>
          <p style={{ color: 'var(--text-secondary)', marginBottom: 20 }}>
            {MOCK_COMPONENTS.length} public symbols exported from this module.
          </p>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
              gap: 16,
              marginBottom: 8,
            }}
          >
            {MOCK_COMPONENTS.map((comp) => (
              <div
                key={comp.name}
                style={{
                  padding: 20,
                  background: 'rgba(255,255,255,0.03)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 14,
                  transition: 'border-color 0.2s',
                }}
              >
                <TypeBadge type={comp.type} style={{ marginBottom: 10 }} />
                <Link
                  href={`${base}/entities/${comp.name.replace('()', '')}`}
                  style={{
                    display: 'block',
                    fontFamily: "'Fira Code', monospace",
                    fontSize: 14,
                    fontWeight: 600,
                    color: 'var(--secondary)',
                    textDecoration: 'none',
                    marginBottom: 8,
                  }}
                >
                  {comp.name}
                </Link>
                <p style={{ fontSize: 13, color: 'var(--text-tertiary)', lineHeight: 1.6 }}>{comp.desc}</p>
              </div>
            ))}
          </div>

          {/* Dependencies */}
          <h2 id="dependencies" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Dependencies
          </h2>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 8 }}>
            {[
              { title: 'Uses (upstream)', items: MOCK_DEPS_UPSTREAM, color: 'var(--secondary)' },
              { title: 'Used by (downstream)', items: MOCK_DEPS_DOWNSTREAM, color: 'var(--primary-light)' },
            ].map((group) => (
              <div key={group.title}>
                <h3 style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-tertiary)', marginBottom: 10 }}>
                  {group.title}
                </h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {group.items.map((dep) => (
                    <Link
                      key={dep}
                      href={`${base}/modules/${dep}`}
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: 6,
                        padding: '6px 12px',
                        background: 'rgba(255,255,255,0.04)',
                        border: '1px solid var(--glass-border)',
                        borderRadius: 8,
                        fontSize: 13,
                        fontFamily: "'Fira Code', monospace",
                        color: group.color,
                        textDecoration: 'none',
                        transition: 'border-color 0.2s',
                      }}
                    >
                      {dep}
                    </Link>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {/* Code Examples */}
          <h2 id="code-examples" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Code Examples
          </h2>
          <CodeBlock language="python">
            {`from src.auth import authenticate_user, create_session

# Authenticate a user and create a session
user = authenticate_user(username="alice", password="secret")
if user:
    token = create_session(user_id=user.id, ttl=3600)
    print(f"Session created: {token}")`}
          </CodeBlock>

          {/* Related Pages */}
          <h2 id="related-pages" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Related Pages
          </h2>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            {['API Reference', 'Getting Started', 'Security Patterns'].map((page) => (
              <Link
                key={page}
                href={`${base}/`}
                style={{
                  padding: '8px 16px',
                  background: 'rgba(255,255,255,0.04)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 10,
                  fontSize: 13,
                  color: 'var(--secondary)',
                  textDecoration: 'none',
                  transition: 'border-color 0.2s',
                }}
              >
                {page}
              </Link>
            ))}
          </div>
        </main>

        {/* ── Right TOC ── */}
        <aside
          style={{
            position: 'sticky',
            top: 0,
            height: '100vh',
            overflowY: 'auto',
            padding: '32px 20px',
          }}
        >
          <TableOfContents items={TOC_ITEMS} />
        </aside>
      </div>
    </>
  );
}

