 */

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { Logo } from '@/components/ui/Logo';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { InfoBox } from '@/components/ui/InfoBox';
import { CodeBlock } from '@/components/ui/CodeBlock';
import { TypeBadge } from '@/components/ui/TypeBadge';
import { TableOfContents } from '@/components/layout/TableOfContents';
import { WikiSidebar } from '@/components/layout/WikiSidebar';
import { api } from '@/services/api';
import type { Module, Repository, WikiPage } from '@/services/api';

const TOC_ITEMS = [
  { id: 'file-location', label: 'File Location', level: 2 },
  { id: 'key-components', label: 'Key Components', level: 2 },
  { id: 'dependencies', label: 'Dependencies', level: 2 },
  { id: 'how-it-works', label: 'How It Works', level: 2 },
  { id: 'related-pages', label: 'Related Pages', level: 2 },
];

/** Extract a short display name from a qualified name like "a.b.c.my_func" */
function shortName(qualifiedName: string): string {
  const parts = qualifiedName.split('.');
  return parts[parts.length - 1] || qualifiedName;
}

export default function ModulePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const slug = params.slug as string;

  const [repo, setRepo] = useState<Repository | null>(null);
  const [module_, setModule] = useState<Module | null>(null);
  const [wikiPage, setWikiPage] = useState<WikiPage | null>(null);
  const [allModules, setAllModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }
        setRepo(found);

        const [mod, page, mods] = await Promise.all([
          api.wikis.getModule(found.id, slug).catch(() => null),
          api.wikis.getPage(found.id, slug).catch(() => null),
          api.wikis.listModules(found.id).catch(() => []),
        ]);
        setModule(mod);
        setWikiPage(page);
        setAllModules(mods);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name, slug]);

  // Pull structured content from the wiki page JSONB
  const content = wikiPage?.content as Record<string, unknown> | null ?? null;
  const overview = content?.overview as { purpose?: string; design_patterns?: string[]; data_flow?: string } | null;
  const keyComponents = (content?.key_components as { name: string; role: string }[] | null) ?? [];
  const deps = content?.dependencies as { internal?: string[]; external?: string[] } | null;
  const howItWorks = (content?.how_it_works as string | null) ?? overview?.data_flow ?? null;
  const knownIssues = (content?.known_issues as string[] | null) ?? [];
  const relatedPages = (content?.related_pages as { name: string; slug: string }[] | null) ?? [];
  const commitHash = (content?.commit_hash as string | null) ?? null;

  const displayName = module_?.name
    ? module_.name.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
    : slug.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());

  const description = overview?.purpose
    ?? module_?.description
    ?? 'Module documentation generated from source code analysis.';

  const filePaths = module_?.file_paths ?? [];

  // Deduplicate modules by slug for sidebar
  const uniqueModules = allModules.filter(
    (m, i, arr) => arr.findIndex((x) => x.slug === m.slug) === i
  );

  const sidebarSections = uniqueModules.length > 0
    ? [{
        label: 'Modules',
        items: uniqueModules.map((m) => ({
          label: m.name || m.slug || '/',
          href: `modules/${m.slug}`,
          active: m.slug === slug,
        })),
      }]
    : [];

  const base = `/${owner}/${name}`;

  return (
    <>
      <GradientBackground />

      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '300px 1fr 280px',
          minHeight: '100vh',
          gap: 0,
        }}
      >
        {/* ── Left sidebar ── */}
        <WikiSidebar pageTitle={`${name} — ${displayName}`} width={300}>
          <div style={{ padding: '0 20px 20px' }}>
            <Logo href={base} />
          </div>

          {sidebarSections.map((section) => (
            <div key={section.label} style={{ marginBottom: 8 }}>
              <div
                style={{
                  padding: '6px 20px',
                  fontSize: 11,
                  fontWeight: 700,
                  textTransform: 'uppercase',
                  letterSpacing: '0.8px',
                  color: 'var(--text-tertiary)',
                }}
              >
                {section.label}
              </div>
              <div>
                {section.items.map((item) => (
                  <Link
                    key={item.href}
                    href={`${base}/${item.href}`}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      padding: '8px 20px',
                      fontSize: 14,
                      fontWeight: 500,
                      textDecoration: 'none',
                      color: item.active ? 'var(--primary-light)' : 'var(--text-secondary)',
                      background: item.active
                        ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(6,182,212,0.1))'
                        : 'transparent',
                      borderLeft: item.active
                        ? '3px solid var(--primary)'
                        : '3px solid transparent',
                      transition: 'all 0.2s',
                    }}
                  >
                    {item.label}
                  </Link>
                ))}
              </div>
            </div>
          ))}

          {/* Static nav links */}
          {[
            { label: 'Wiki Home', href: base },
            { label: 'Getting Started', href: `${base}/getting-started` },
            { label: 'API Reference', href: `${base}/api` },
            { label: 'Glossary', href: `${base}/glossary` },
          ].map((link) => (
            <Link
              key={link.href}
              href={link.href}
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '8px 20px',
                fontSize: 14,
                fontWeight: 500,
                textDecoration: 'none',
                color: 'var(--text-secondary)',
                borderLeft: '3px solid transparent',
                transition: 'all 0.2s',
              }}
            >
              {link.label}
            </Link>
          ))}
        </WikiSidebar>

        {/* ── Main content ── */}
        <main
          className="wiki-main"
          style={{
            padding: '32px 40px',
            minWidth: 0,
            background: 'var(--glass-bg)',
            backdropFilter: 'blur(20px)',
            borderRight: '1px solid var(--glass-border)',
          }}
        >
          <Breadcrumbs
            crumbs={[
              { label: 'dashboard', href: '/dashboard' },
              { label: `${name} wiki`, href: base },
              { label: 'Modules', href: `${base}/modules` },
              { label: displayName },
            ]}
          />

          <h1
            style={{
              fontSize: 32,
              fontWeight: 800,
              marginTop: 24,
              marginBottom: 8,
              letterSpacing: '-0.02em',
            }}
          >
            {displayName} Module
          </h1>

          {/* Sync meta */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              fontSize: 13,
              color: 'var(--text-tertiary)',
              marginBottom: 24,
              flexWrap: 'wrap',
            }}
          >
            <span
              style={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                background: 'var(--success)',
                display: 'inline-block',
                boxShadow: '0 0 6px var(--success)',
              }}
            />
            {commitHash ? (
              <>
                <span>Commit:</span>
                <span style={{ fontFamily: "'Fira Code', monospace", color: 'var(--primary-light)' }}>
                  {commitHash.slice(0, 7)}
                </span>
                <span>·</span>
              </>
            ) : null}
            <span>Auto-generated from source</span>
          </div>

          {loading ? (
            <div style={{ color: 'var(--text-tertiary)', padding: '40px 0' }}>Loading…</div>
          ) : (
            <>
              <div className="content-body">
                <p style={{ color: 'var(--text-secondary)', lineHeight: 1.8, marginBottom: 24 }}>
                  {description}
                </p>
              </div>

              <InfoBox variant="info">
                <strong>Auto-generated:</strong> This page is generated directly from source code in{' '}
                <code>{filePaths[0] ?? `${slug}/`}</code>. All function signatures, file sizes, and dependency
