              </InfoBox>

              {/* File Location */}
              <h2 id="file-location" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                File Location
              </h2>
              <CodeBlock language="text">
                {filePaths.length > 0
                  ? filePaths.slice(0, 10).join('\n')
                  : `${slug}/`}
              </CodeBlock>

              {/* Key Components */}
              <h2 id="key-components" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
