import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { InfoBox } from '@/components/ui/InfoBox';
import { CodeBlock } from '@/components/ui/CodeBlock';
import { TypeBadge } from '@/components/ui/TypeBadge';
import { TableOfContents } from '@/components/layout/TableOfContents';
import { WikiSidebar } from '@/components/layout/WikiSidebar';
import { api } from '@/services/api';
import type { Module, Repository, WikiPage } from '@/services/api';

const TOC_ITEMS = [
  { id: 'file-location', label: 'File Location', level: 2 },
  { id: 'key-components', label: 'Key Components', level: 2 },
  { id: 'dependencies', label: 'Dependencies', level: 2 },
  { id: 'how-it-works', label: 'How It Works', level: 2 },
  { id: 'related-pages', label: 'Related Pages', level: 2 },
];

/** Extract a short display name from a qualified name like "a.b.c.my_func" */
function shortName(qualifiedName: string): string {
  const parts = qualifiedName.split('.');
  return parts[parts.length - 1] || qualifiedName;
}

export default function ModulePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const slug = params.slug as string;

  const [repo, setRepo] = useState<Repository | null>(null);
  const [module_, setModule] = useState<Module | null>(null);
  const [wikiPage, setWikiPage] = useState<WikiPage | null>(null);
  const [allModules, setAllModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }
        setRepo(found);

        const [mod, page, mods] = await Promise.all([
          api.wikis.getModule(found.id, slug).catch(() => null),
          api.wikis.getPage(found.id, slug).catch(() => null),
          api.wikis.listModules(found.id).catch(() => []),
        ]);
        setModule(mod);
        setWikiPage(page);
        setAllModules(mods);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name, slug]);

  // Pull structured content from the wiki page JSONB
  const content = wikiPage?.content as Record<string, unknown> | null ?? null;
  const overview = content?.overview as { purpose?: string; design_patterns?: string[]; data_flow?: string } | null;
  const keyComponents = (content?.key_components as { name: string; role: string }[] | null) ?? [];
  const deps = content?.dependencies as { internal?: string[]; external?: string[] } | null;
  const howItWorks = (content?.how_it_works as string | null) ?? overview?.data_flow ?? null;
  const knownIssues = (content?.known_issues as string[] | null) ?? [];
  const relatedPages = (content?.related_pages as { name: string; slug: string }[] | null) ?? [];
  const commitHash = (content?.commit_hash as string | null) ?? null;

  const displayName = module_?.name
    ? module_.name.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
    : slug.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());

  const description = overview?.purpose
    ?? module_?.description
    ?? 'Module documentation generated from source code analysis.';

  const filePaths = module_?.file_paths ?? [];

  // Deduplicate modules by slug for sidebar
  const uniqueModules = allModules.filter(
    (m, i, arr) => arr.findIndex((x) => x.slug === m.slug) === i
  );

  const sidebarSections = uniqueModules.length > 0
    ? [{
        label: 'Modules',
        items: uniqueModules.map((m) => ({
          label: m.name || m.slug || '/',
          href: `modules/${m.slug}`,
          active: m.slug === slug,
        })),
      }]
    : [];

  const base = `/${owner}/${name}`;

  return (
    <>
      <GradientBackground />

      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '300px 1fr 280px',
          minHeight: '100vh',
          gap: 0,
        }}
      >
        {/* ── Left sidebar ── */}
        <WikiSidebar pageTitle={`${name} — ${displayName}`} width={300}>
          <div style={{ padding: '0 20px 20px' }}>
            <Logo href={base} />
          </div>

          {sidebarSections.map((section) => (
            <div key={section.label} style={{ marginBottom: 8 }}>
              <div
                style={{
                  padding: '6px 20px',
                  fontSize: 11,
                  fontWeight: 700,
                  textTransform: 'uppercase',
                  letterSpacing: '0.8px',
                  color: 'var(--text-tertiary)',
                }}
              >
                {section.label}
              </div>
              <div>
                {section.items.map((item) => (
                  <Link
                    key={item.href}
                    href={`${base}/${item.href}`}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      padding: '8px 20px',
                      fontSize: 14,
                      fontWeight: 500,
                      textDecoration: 'none',
                      color: item.active ? 'var(--primary-light)' : 'var(--text-secondary)',
                      background: item.active
                        ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(6,182,212,0.1))'
                        : 'transparent',
                      borderLeft: item.active
                        ? '3px solid var(--primary)'
                        : '3px solid transparent',
                      transition: 'all 0.2s',
                    }}
                  >
                    {item.label}
                  </Link>
                ))}
              </div>
            </div>
          ))}

          {/* Static nav links */}
          {[
            { label: 'Wiki Home', href: base },
            { label: 'Getting Started', href: `${base}/getting-started` },
            { label: 'API Reference', href: `${base}/api` },
            { label: 'Glossary', href: `${base}/glossary` },
          ].map((link) => (
            <Link
              key={link.href}
              href={link.href}
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '8px 20px',
                fontSize: 14,
                fontWeight: 500,
                textDecoration: 'none',
                color: 'var(--text-secondary)',
                borderLeft: '3px solid transparent',
                transition: 'all 0.2s',
              }}
            >
              {link.label}
            </Link>
          ))}
        </WikiSidebar>

        {/* ── Main content ── */}
        <main
          className="wiki-main"
          style={{
            padding: '32px 40px',
            minWidth: 0,
            background: 'var(--glass-bg)',
            backdropFilter: 'blur(20px)',
            borderRight: '1px solid var(--glass-border)',
          }}
        >
          <Breadcrumbs
            crumbs={[
              { label: 'dashboard', href: '/dashboard' },
              { label: `${name} wiki`, href: base },
              { label: 'Modules', href: `${base}/modules` },
              { label: displayName },
            ]}
          />

          <h1
            style={{
              fontSize: 32,
              fontWeight: 800,
              marginTop: 24,
              marginBottom: 8,
              letterSpacing: '-0.02em',
            }}
          >
            {displayName} Module
          </h1>

          {/* Sync meta */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              fontSize: 13,
              color: 'var(--text-tertiary)',
              marginBottom: 24,
              flexWrap: 'wrap',
            }}
          >
            <span
              style={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                background: 'var(--success)',
                display: 'inline-block',
                boxShadow: '0 0 6px var(--success)',
              }}
            />
            {commitHash ? (
              <>
                <span>Commit:</span>
                <span style={{ fontFamily: "'Fira Code', monospace", color: 'var(--primary-light)' }}>
                  {commitHash.slice(0, 7)}
                </span>
                <span>·</span>
              </>
            ) : null}
            <span>Auto-generated from source</span>
          </div>

          {loading ? (
            <div style={{ color: 'var(--text-tertiary)', padding: '40px 0' }}>Loading…</div>
          ) : (
            <>
              <div className="content-body">
                <p style={{ color: 'var(--text-secondary)', lineHeight: 1.8, marginBottom: 24 }}>
                  {description}
                </p>
              </div>

              <InfoBox variant="info">
                <strong>Auto-generated:</strong> This page is generated directly from source code in{' '}
                <code>{filePaths[0] ?? `${slug}/`}</code>. All function signatures, file sizes, and dependency
                data are extracted at analysis time and stay in sync with every commit.
              </InfoBox>

              {/* File Location */}
              <h2 id="file-location" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                File Location
              </h2>
              <CodeBlock language="text">
                {filePaths.length > 0
                  ? filePaths.slice(0, 10).join('\n')
                  : `${slug}/`}
              </CodeBlock>

              {/* Key Components */}
              <h2 id="key-components" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                Key Components
              </h2>
              {keyComponents.length > 0 ? (
                <>
                  <p style={{ color: 'var(--text-secondary)', marginBottom: 20 }}>
                    {keyComponents.length} key component{keyComponents.length !== 1 ? 's' : ''} in this module.
                  </p>
                  <div
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
                      gap: 16,
                      marginBottom: 8,
                    }}
                  >
                    {keyComponents.map((comp) => (
                      <div
                        key={comp.name}
                        style={{
                          padding: 20,
                          background: 'rgba(255,255,255,0.03)',
                          border: '1px solid var(--glass-border)',
                          borderRadius: 14,
                          transition: 'border-color 0.2s',
                        }}
                      >
                        <TypeBadge type="function" style={{ marginBottom: 10 }} />
                        <div
                          style={{
                            fontFamily: "'Fira Code', monospace",
                            fontSize: 13,
                            fontWeight: 600,
                            color: 'var(--secondary)',
                            marginBottom: 8,
                            wordBreak: 'break-all',
                          }}
                        >
                          {shortName(comp.name)}
                        </div>
                        <p style={{ fontSize: 13, color: 'var(--text-tertiary)', lineHeight: 1.6 }}>{comp.role}</p>
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <p style={{ color: 'var(--text-tertiary)' }}>No components indexed for this module.</p>
              )}

              {/* Dependencies */}
              <h2 id="dependencies" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                Dependencies
              </h2>
              {deps ? (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 8 }}>
                  {[
                    { title: 'Internal', items: deps.internal ?? [], color: 'var(--secondary)' },
                    { title: 'External', items: deps.external ?? [], color: 'var(--primary-light)' },
                  ].map((group) => (
                    <div key={group.title}>
                      <h3 style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-tertiary)', marginBottom: 10 }}>
                        {group.title}
                      </h3>
                      {group.items.length > 0 ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                          {group.items.map((dep) => (
                            <span
                              key={dep}
                              style={{
                                display: 'inline-flex',
                                alignItems: 'center',
                                gap: 6,
                                padding: '6px 12px',
                                background: 'rgba(255,255,255,0.04)',
                                border: '1px solid var(--glass-border)',
                                borderRadius: 8,
                                fontSize: 12,
                                fontFamily: "'Fira Code', monospace",
                                color: group.color,
                              }}
                            >
                              {shortName(dep)}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <span style={{ fontSize: 13, color: 'var(--text-tertiary)' }}>None</span>
                      )}
                    </div>
                  ))}
                </div>
              ) : (
                <p style={{ color: 'var(--text-tertiary)' }}>No dependency data available.</p>
              )}

              {/* How It Works */}
              {howItWorks && (
                <>
                  <h2 id="how-it-works" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                    How It Works
                  </h2>
                  <p style={{ color: 'var(--text-secondary)', lineHeight: 1.8, marginBottom: 16 }}>
                    {howItWorks}
                  </p>
                  {overview?.design_patterns && overview.design_patterns.length > 0 && (
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                      {overview.design_patterns.map((p) => (
                        <span
                          key={p}
                          style={{
                            padding: '4px 12px',
                            background: 'rgba(139,92,246,0.12)',
                            border: '1px solid rgba(139,92,246,0.25)',
                            borderRadius: 20,
                            fontSize: 12,
                            color: 'var(--primary-light)',
                          }}
                        >
                          {p}
                        </span>
                      ))}
                    </div>
                  )}
                </>
              )}

              {/* Known Issues */}
              {knownIssues.length > 0 && (
                <InfoBox variant="warning" style={{ marginTop: 24 }}>
                  <strong>Known Issues:</strong>
                  <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
                    {knownIssues.map((issue, i) => (
                      <li key={i} style={{ marginBottom: 4 }}>{issue}</li>
                    ))}
                  </ul>
                </InfoBox>
              )}

              {/* Related Pages */}
              {relatedPages.length > 0 && (
                <>
                  <h2 id="related-pages" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
                    Related Pages
                  </h2>
                  <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                    {relatedPages.map((page) => (
                      <Link
                        key={page.slug}
                        href={`${base}/modules/${page.slug}`}
                        style={{
                          padding: '8px 16px',
                          background: 'rgba(255,255,255,0.04)',
                          border: '1px solid var(--glass-border)',
                          borderRadius: 10,
                          fontSize: 13,
                          color: 'var(--secondary)',
                          textDecoration: 'none',
                          transition: 'border-color 0.2s',
                        }}
                      >
                        {page.name}
                      </Link>
                    ))}
                  </div>
                </>
              )}
            </>
          )}
        </main>

        {/* ── Right TOC ── */}
        <aside
          style={{
            position: 'sticky',
            top: 0,
            height: '100vh',
            overflowY: 'auto',
            padding: '32px 20px',
          }}
        >
          <TableOfContents items={TOC_ITEMS} />
        </aside>
      </div>
    </>
  );
}

