'use client';

/**
 * Module page — 3-column wiki layout for a code module.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/module.html
 */

import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { InfoBox } from '@/components/ui/InfoBox';
import { CodeBlock } from '@/components/ui/CodeBlock';
import { TypeBadge } from '@/components/ui/TypeBadge';
import { TableOfContents } from '@/components/layout/TableOfContents';
import { WikiSidebar } from '@/components/layout/WikiSidebar';
import { api } from '@/services/api';
import type { Module, Repository } from '@/services/api';

const MOCK_COMPONENTS = [
  { type: 'class' as const, name: 'AuthenticationMiddleware', desc: 'Express-compatible middleware that validates incoming JWT tokens and attaches the decoded user context to the request object.' },
  { type: 'function' as const, name: 'authenticate_user()', desc: 'Primary entry point — validates credentials against the database and returns a signed JWT on success.' },
  { type: 'function' as const, name: 'create_session()', desc: 'Creates a new server-side session record in Redis and returns the session identifier to the caller.' },
  { type: 'function' as const, name: 'verify_token()', desc: 'Cryptographically verifies a JWT signature and expiry, returning the decoded payload or raising an error.' },
  { type: 'function' as const, name: 'refresh_token()', desc: 'Issues a new access token from a valid refresh token without requiring the user to re-authenticate.' },
  { type: 'function' as const, name: 'logout()', desc: 'Invalidates the current session in Redis and marks the JWT as revoked in the token blocklist.' },
];

const MOCK_DEPS_UPSTREAM = ['database', 'config', 'utils/crypto'];
const MOCK_DEPS_DOWNSTREAM = ['api/routes', 'middleware', 'admin'];

const TOC_ITEMS = [
  { id: 'file-location', label: 'File Location', level: 2 },
  { id: 'key-components', label: 'Key Components', level: 2 },
  { id: 'dependencies', label: 'Dependencies', level: 2 },
  { id: 'code-examples', label: 'Code Examples', level: 2 },
  { id: 'related-pages', label: 'Related Pages', level: 2 },
];

const SIDEBAR_SECTIONS = [
  {
    label: 'Getting Started',
    items: [
      { label: 'Overview', href: 'getting-started' },
      { label: 'Quick Start', href: 'getting-started' },
    ],
  },
  {
    label: 'Core Concepts',
    items: [
      { label: 'Module Detection', href: 'modules/module-detection' },
      { label: 'Code Parsing', href: 'modules/code-parsing' },
    ],
  },
  {
    label: 'Features',
    items: [
      { label: 'AI Chat Assistant', href: 'chat' },
      { label: 'Visual Diagrams', href: 'diagrams' },
      { label: 'Search', href: 'search' },
    ],
  },
  {
    label: 'API Reference',
    items: [
      { label: 'Function Index', href: 'api' },
      { label: 'Glossary', href: 'glossary' },
    ],
  },
];

export default function ModulePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const slug = params.slug as string;

  const [repo, setRepo] = useState<Repository | null>(null);
  const [module_, setModule] = useState<Module | null>(null);
  const [loading, setLoading] = useState(true);
  const [allModules, setAllModules] = useState<Module[]>([]);

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }
        setRepo(found);

        const [mod, mods] = await Promise.all([
          api.wikis.getModule(found.id, slug).catch(() => null),
          api.wikis.listModules(found.id).catch(() => []),
        ]);
        setModule(mod);
        setAllModules(mods);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name, slug]);

  const displayModule = module_ ?? {
    name: slug.charAt(0).toUpperCase() + slug.slice(1).replace(/-/g, ' '),
    description: 'Authentication module handles all aspects of user identity and access. It provides JWT-based session management, password hashing, token lifecycle, and HTTP middleware for protecting routes.',
    file_paths: ['src/auth/'],
    file_count: 18,
  };

  // Build sidebar items, marking current module as active
  const sidebarSections = allModules.length > 0
    ? [{
        label: 'Modules',
        items: allModules.map((m) => ({
          label: m.name,
          href: `modules/${m.slug}`,
          active: m.slug === slug,
        })),
      }, ...SIDEBAR_SECTIONS]
    : SIDEBAR_SECTIONS.map((s) => ({
        ...s,
        items: s.items.map((item) => ({
          ...item,
          active: item.href === `modules/${slug}`,
        })),
      }));

  const base = `/${owner}/${name}`;

  return (
    <>
      <GradientBackground />

      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '300px 1fr 280px',
          minHeight: '100vh',
          gap: 0,
        }}
      >
        {/* ── Left sidebar ── */}
        <WikiSidebar pageTitle={`${name} — ${displayModule.name}`} width={300}>
          <div style={{ padding: '0 20px 20px' }}>
            <Logo href={base} />
          </div>

          {sidebarSections.map((section) => (
            <div key={section.label} style={{ marginBottom: 8 }}>
              <div
                style={{
                  padding: '6px 20px',
                  fontSize: 11,
                  fontWeight: 700,
                  textTransform: 'uppercase',
                  letterSpacing: '0.8px',
                  color: 'var(--text-tertiary)',
                }}
              >
                {section.label}
              </div>
              <div>
                {section.items.map((item) => (
                  <Link
                    key={item.label}
                    href={`${base}/${item.href}`}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      padding: '8px 20px',
                      fontSize: 14,
                      fontWeight: 500,
                      textDecoration: 'none',
                      color: (item as { active?: boolean }).active ? 'var(--primary-light)' : 'var(--text-secondary)',
                      background: (item as { active?: boolean }).active
                        ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(6,182,212,0.1))'
                        : 'transparent',
                      borderLeft: (item as { active?: boolean }).active
                        ? '3px solid var(--primary)'
                        : '3px solid transparent',
                      transition: 'all 0.2s',
                    }}
                  >
                    {item.label}
                  </Link>
                ))}
              </div>
            </div>
          ))}
        </WikiSidebar>

        {/* ── Main content ── */}
        <main
          className="wiki-main"
          style={{
            padding: '32px 40px',
            minWidth: 0,
            background: 'var(--glass-bg)',
            backdropFilter: 'blur(20px)',
            borderRight: '1px solid var(--glass-border)',
          }}
        >
          {/* Breadcrumbs */}
          <Breadcrumbs
            crumbs={[
              { label: 'dashboard', href: '/dashboard' },
              { label: `${name} wiki`, href: base },
              { label: 'Modules', href: `${base}/modules` },
              { label: displayModule.name },
            ]}
          />

          <h1
            style={{
              fontSize: 32,
              fontWeight: 800,
              marginTop: 24,
              marginBottom: 8,
              letterSpacing: '-0.02em',
            }}
          >
            {displayModule.name} Module
          </h1>

          {/* Sync meta */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              fontSize: 13,
              color: 'var(--text-tertiary)',
              marginBottom: 24,
              flexWrap: 'wrap',
            }}
          >
            <span
              style={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                background: 'var(--success)',
                display: 'inline-block',
                boxShadow: '0 0 6px var(--success)',
              }}
            />
            <span>Last synced:</span>
            <span style={{ fontFamily: "'Fira Code', monospace", color: 'var(--primary-light)' }}>
              f6c11de
            </span>
            <span>· 2 hours ago</span>
            <span>· Auto-generated from source</span>
          </div>

          <div className="content-body">
            <p style={{ color: 'var(--text-secondary)', lineHeight: 1.8, marginBottom: 24 }}>
              {displayModule.description}
            </p>
          </div>

          <InfoBox variant="info">
            <strong>Auto-generated:</strong> This page is generated directly from source code in{' '}
            <code>{displayModule.file_paths?.[0] ?? 'src/'}</code>. All function signatures, file sizes, and dependency
            data are extracted at analysis time and stay in sync with every commit.
          </InfoBox>

          {/* File Location */}
          <h2 id="file-location" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            File Location
          </h2>
          <CodeBlock language="text">
            {`${displayModule.file_paths?.[0] ?? 'src/auth/'}
  ├── login.py         (245 lines)
  ├── session.py       (189 lines)
  ├── tokens.py        (312 lines)
  └── middleware.py    (201 lines)`}
