                  ))}
                </div>
              </div>
            ))}
          </div>

          {/* Code Examples */}
          <h2 id="code-examples" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Code Examples
          </h2>
          <CodeBlock language="python">
            {`from src.auth import authenticate_user, create_session

# Authenticate a user and create a session
user = authenticate_user(username="alice", password="secret")
if user:
    token = create_session(user_id=user.id, ttl=3600)
    print(f"Session created: {token}")`}
          </CodeBlock>

          {/* Related Pages */}
          <h2 id="related-pages" style={{ fontSize: 22, fontWeight: 700, margin: '36px 0 16px' }}>
            Related Pages
          </h2>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            {['API Reference', 'Getting Started', 'Security Patterns'].map((page) => (
              <Link
                key={page}
                href={`${base}/`}
                style={{
                  padding: '8px 16px',
                  background: 'rgba(255,255,255,0.04)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 10,
                  fontSize: 13,
                  color: 'var(--secondary)',
                  textDecoration: 'none',
                  transition: 'border-color 0.2s',
                }}
              >
                {page}
              </Link>
            ))}
          </div>
        </main>

        {/* ── Right TOC ── */}
        <aside
          style={{
            position: 'sticky',
            top: 0,
            height: '100vh',
            overflowY: 'auto',
            padding: '32px 20px',
          }}
        >
          <TableOfContents items={TOC_ITEMS} />
        </aside>
      </div>
    </>
  );
}

