def _detect_modules(local_path: Path, entities: list[ParsedEntity], fingerprint) -> list[dict]:
    """Group entities into modules based on directory structure."""
    # Resolve to absolute so relative_to() works for entities whose file_path
    # was already absolutized by the TypeScript extractor (path.resolve()).
    local_path = local_path.resolve()
    modules: dict[str, list[ParsedEntity]] = {}

    for entity in entities:
        if entity.entity_type == "module":
            continue
        # Use parent directory as module
        try:
            rel = str(Path(entity.file_path).relative_to(local_path))
        except ValueError:
            rel = entity.file_path

        parts = Path(rel).parts
        if len(parts) >= 2:
            module_dir = parts[0]
        else:
            module_dir = "root"

        # Skip metadata dirs
        if module_dir in _SKIP_DIRS:
            continue

        modules.setdefault(module_dir, []).append(entity)

    result = []
    for mod_name, mod_entities in modules.items():
        files = list({e.file_path for e in mod_entities})[:20]
        rel_files = []
        for f in files:
            try:
                rel_files.append(str(Path(f).relative_to(local_path)))
            except ValueError:
                rel_files.append(f)
        result.append({
            "name": mod_name,
            "slug": slugify(mod_name),
            "entities": mod_entities,
            "file_paths": rel_files,
            "file_count": len(files),
            "description": "",
        })

    return result


