'use client';

/**
 * Wiki Home page — repository overview with stats, quick links, and module grid.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/home.html
 */

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { api } from '@/services/api';
import type { Repository, Module } from '@/services/api';

const QUICK_LINKS = [
  { icon: '🚀', title: 'Getting Started', desc: 'Setup instructions, prerequisites, and quick start guide', href: 'getting-started' },
  { icon: '🔍', title: 'API Reference', desc: 'Complete searchable index of all functions and classes', href: 'api' },
  { icon: '💬', title: 'AI Assistant', desc: 'Ask questions about the codebase and get instant answers', href: 'chat' },
  { icon: '📈', title: 'Diagrams', desc: 'Architecture diagrams, dependency graphs, and relationship visualizations', href: 'diagrams' },
  { icon: '📖', title: 'Glossary', desc: 'Auto-detected domain terms and concepts from your codebase', href: 'glossary' },
];

const MODULE_ICONS = ['🔐', '📊', '💬', '📄', '🔍', '📈', '🔄', '🗄️'];

export default function WikiHomePage() {
  const params = useParams();
  const router = useRouter();
  const owner = params.owner as string;
  const name = params.name as string;

  const [repo, setRepo] = useState<Repository | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const load = async () => {
      try {
        // Find repo by owner/name from list
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }
        setRepo(found);

        // Load modules
        const mods = await api.wikis.listModules(found.id).catch(() => []);
        setModules(mods);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      router.push(`/${owner}/${name}/search?q=${encodeURIComponent(searchQuery)}`);
    }
  };

  // Fallback stats from repo or modules
  const moduleCount = repo ? (modules.length || 8) : 8;
  const funcCount = modules.reduce((acc, m) => acc + (m.file_count ?? 0), 0) || 142;
  const classCount = 28;
  const loc = repo?.size_lines ? (repo.size_lines / 1000).toFixed(1) + 'k' : '45.2k';

  const displayModules = modules.length > 0 ? modules : [
    { id: '1', name: 'Authentication', slug: 'authentication', description: 'User authentication system with JWT tokens, OAuth integration, and session management.', file_paths: ['src/auth/'], file_count: 18, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
    { id: '2', name: 'Repository Analysis', slug: 'analysis', description: 'Code parsing engine that analyzes repository structure, detects modules, and builds knowledge graphs.', file_paths: ['src/analysis/'], file_count: 24, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
    { id: '3', name: 'AI Chat Interface', slug: 'chat', description: 'Conversational AI assistant for answering questions about codebase with contextual understanding.', file_paths: ['src/chat/'], file_count: 16, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
    { id: '4', name: 'Wiki Generation', slug: 'wiki', description: 'Automatic wiki page generation from code analysis with structured sections and hyperlinks.', file_paths: ['src/wiki/'], file_count: 20, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
    { id: '5', name: 'Search Engine', slug: 'search', description: 'Full-text search with semantic understanding for finding functions, classes, and concepts.', file_paths: ['src/search/'], file_count: 14, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
    { id: '6', name: 'Diagram Generator', slug: 'diagrams', description: 'Visual architecture diagrams, dependency graphs, and relationship visualizations.', file_paths: ['src/diagrams/'], file_count: 12, line_count: 0, wiki_id: '', dependencies_module_ids: [] },
  ] as unknown as Module[];

  const TIMELINE_ITEMS = [
    { icon: '📝', text: 'Wiki updated', time: '2 hours ago', detail: 'Commit f6c11de — 3 modules updated' },
    { icon: '🔄', text: 'Sync triggered', time: '6 hours ago', detail: 'Auto-sync from push webhook' },
    { icon: '✅', text: 'Analysis complete', time: 'Yesterday', detail: 'Initial wiki generation' },
  ];

  return (
    <>
      <GradientBackground />
      <div style={{ maxWidth: 1400, margin: '0 auto', padding: '0 24px 80px' }}>

        {/* ── Header card ── */}
        <GlassCard
          style={{ padding: '32px 36px', marginBottom: 28, marginTop: 24 }}
          className="animate-fade-in-up"
        >
          {/* Top row: logo + search + CTA */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 16,
              marginBottom: 28,
              flexWrap: 'wrap',
            }}
          >
            <Logo href="/dashboard" size="sm" />

            <form
              onSubmit={handleSearch}
              style={{
                flex: 1,
                minWidth: 200,
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                background: 'rgba(255,255,255,0.05)',
                border: '1px solid var(--glass-border)',
                borderRadius: 12,
                padding: '10px 16px',
              }}
            >
              <span style={{ fontSize: 16 }}>🔍</span>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search modules, functions, classes…"
                style={{
                  flex: 1,
                  background: 'none',
                  border: 'none',
                  outline: 'none',
                  color: 'var(--text-primary)',
                  fontFamily: "'Outfit', sans-serif",
                  fontSize: 14,
                }}
              />
            </form>

            <Link
              href={`/${owner}/${name}/chat`}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                padding: '10px 20px',
                background: 'linear-gradient(135deg, var(--primary), var(--secondary))',
                borderRadius: 12,
                color: 'white',
                fontWeight: 600,
                fontSize: 14,
                textDecoration: 'none',
                flexShrink: 0,
              }}
            >
              💬 Ask AI
            </Link>
          </div>

          {/* Repo info */}
          <h1
            style={{
              fontFamily: "'Fira Code', monospace",
              fontSize: 28,
              fontWeight: 700,
              marginBottom: 10,
            }}
          >
            {name}
          </h1>
          <p style={{ color: 'var(--text-secondary)', marginBottom: 16, maxWidth: 700, lineHeight: 1.6 }}>
            AI-powered code documentation platform that generates and maintains comprehensive,
            structured wiki for any codebase.
          </p>

          {/* Meta chips */}
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
            {[
              { icon: '⚡', label: (repo?.primary_languages?.[0] ?? 'TypeScript') },
              { icon: '🕒', label: repo?.last_analyzed_at ? `Updated ${new Date(repo.last_analyzed_at).toLocaleDateString()}` : 'Last analyzed: 2 hours ago' },
              { icon: '📁', label: `${repo?.size_files?.toLocaleString() ?? '312'} files` },
            ].map((m) => (
              <span
                key={m.label}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                  padding: '4px 12px',
                  background: 'rgba(255,255,255,0.05)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 20,
                  fontSize: 13,
                  color: 'var(--text-tertiary)',
                }}
              >
                {m.icon} {m.label}
              </span>
            ))}
          </div>
        </GlassCard>

        {/* ── Stats grid ── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4, 1fr)',
            gap: 16,
            marginBottom: 28,
          }}
          className="stagger"
        >
          {[
            { value: moduleCount, label: 'Modules' },
            { value: funcCount, label: 'Functions' },
            { value: classCount, label: 'Classes' },
            { value: loc, label: 'Lines of Code' },
