            margin-bottom: 48px;
            opacity: 0;
            animation: fadeInUp 0.6s 0.2s ease forwards;
        }

        .stat-card {
            padding: 24px;
            background: linear-gradient(135deg, rgba(139, 92, 246, 0.1), rgba(6, 182, 212, 0.1));
