            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .timeline-meta {
            font-size: 12px;
            color: var(--text-tertiary);
        }

        /* Animations */
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* Mobile Navigation */
        .mobile-nav {
            display: none;
            position: fixed;
            bottom: 24px;
            right: 24px;
            z-index: 1000;
        }

        .mobile-menu-btn {
            width: 56px;
            height: 56px;
