            cursor: pointer;
            box-shadow: 0 8px 30px rgba(139, 92, 246, 0.5);
            transition: all 0.3s;
        }

        .mobile-menu-btn:hover {
            transform: scale(1.1);
        }

        /* Responsive */
        @media (max-width: 768px) {
            .container {
                padding: 16px;
            }

            .header {
                padding: 20px;
            }

            .header-top {
                flex-direction: column;
                align-items: stretch;
            }

            .search-bar {
                width: 100%;
                order: 3;
            }

            .header-actions {
                width: 100%;
                justify-content: space-between;
            }

            .repo-title {
                font-size: 36px;
            }

            .repo-description {
                font-size: 16px;
            }

            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .links-grid {
                grid-template-columns: 1fr;
            }

            .modules-grid {
                grid-template-columns: 1fr;
            }

            .mobile-nav {
                display: block;
            }

            .timeline-item {
                flex-direction: column;
            }
        }

        @media (max-width: 480px) {
            .repo-title {
                font-size: 28px;
            }

            .stats-grid {
                grid-template-columns: 1fr;
            }

            .stat-value {
                font-size: 28px;
            }

            .module-stats {
                flex-direction: column;
                gap: 8px;
            }
        }
